1.10 Reading and Displaying Images
In libraries such as NumPy, OpenCV, and scikit-image, digital images are often computationally represented as NumPy arrays. Thus, matrix operations and linear algebra concepts can be applied directly to digital image processing (DIP).
One of the fundamental operations in DIP is image reading. In the morph.py library, the mm.read() function allows loading images from both local files and URLs, as illustrated in Figure 1.7..

%%writefile tmp/fig_01_natureza.cpp
#define MM_OUT "tmp/fig_01_natureza.png"
// Compile with: g++ -std=c++17 -I. -o program program.cpp -lcurl

#include "morph.hpp"
#include &lt;iostream&gt;
#include &lt;string&gt;
#include &lt;sys/stat.h&gt;
#include &lt;sys/types.h&gt;
#include &lt;filesystem&gt;

int main() {
    // #| label: fig-01-natureza
    // #| fig-cap: "Mandrill (Mandrillus sphinx) in natural environment. Credit: Julien Renoult (CC BY 4.0)."
    // #| echo: true

    std::string url     = "https://upload.wikimedia.org/wikipedia/commons/8/87/Mandrillus_sphinx_339428057.jpg";
    std::string caminho = "imagens/mandrill.png";

    mm::Image img_obj;

    struct stat st;
    if (stat(caminho.c_str(), &st) != 0) {
        mkdir("imagens", 0755);
        img_obj = mm::read(url);
        mm::write(img_obj, caminho);
    } else {
        img_obj = mm::read(caminho);
    }

    mm::Image img = img_obj;

    std::cout &lt;&lt; "Dimensions (H, W, Channels): " &lt;&lt; img.h &lt;&lt; ", " &lt;&lt; img.w &lt;&lt; ", " &lt;&lt; img.channels &lt;&lt; std::endl;
    std::cout &lt;&lt; "Data type: uint8" &lt;&lt; std::endl;

    mm::show(img, MM_OUT, "Exemplo: Captura RGB");


// [pdi:state-io] auto-generated — do not edit by hand
std::filesystem::create_directories("tmp/state");
mm::write(img, "tmp/state/img_24.png");
// [pdi:state-io:end]
return 0;
}

